//! Pinned-C parity for the detector.
//!
//! Replays every committed fixture through the Rust `Detector` and compares the
//! boolean cut, shot age, and internal state digests against `reference.json`, which
//! is generated by the pinned WWXD C control (`oracle/wwxd-reference`). The Rust test
//! and the oracle read the identical prepared blobs, so parity is measured on one
//! input, not two preparation paths. The default test run does not compile C;
//! it reads the committed `reference.json`.

use std::path::{Path, PathBuf};

use serde_json::Value;
use wwxds_core::detect::{Detector, DetectorFrame};
use wwxds_core::frame_index::SourceFrameIndex;

/// The committed fixtures live outside this crate.
///
/// They are written by the C oracle and diffed by CI at the repository path, so
/// they stay where they are and this crate reaches across to them rather than
/// the oracle being repointed at a moved file.
fn fixture_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
        .join("tests")
        .join("fixtures")
        .join("detect")
}

fn load_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).unwrap_or_else(|_| {
        panic!(
            "missing {}; run the fixture/oracle generators",
            path.display()
        )
    });
    serde_json::from_str(&text).expect("valid JSON")
}

/// Replay one fixture through the Rust detector and return per-frame records.
fn replay(manifest_entry: &Value, blob: &[u8]) -> Vec<(bool, i32, u64, u64)> {
    let width = manifest_entry["width"].as_i64().unwrap() as u32;
    let height = manifest_entry["height"].as_i64().unwrap() as u32;
    let stride = manifest_entry["stride"].as_i64().unwrap() as usize;
    let frames = manifest_entry["frames"].as_i64().unwrap() as usize;

    let mut detector = Detector::new(width, height).expect("fixture dimensions are valid");
    let frame_bytes = (height as usize) * stride;
    let mut out = Vec::with_capacity(frames);
    for index in 0..frames {
        let plane = &blob[index * frame_bytes..(index + 1) * frame_bytes];
        let frame = DetectorFrame {
            index: SourceFrameIndex::new(index as u64),
            width,
            height,
            stride,
            luma: plane,
        };
        let decision = detector.process(frame).expect("fixture frame accepted");
        let digests = detector.state_digests();
        out.push((
            decision.is_cut(),
            detector.shot_age(),
            digests.predictors,
            digests.previous_plane,
        ));
    }
    out
}

#[test]
fn detector_matches_pinned_wwxd_on_every_fixture() {
    let dir = fixture_dir();
    let manifest = load_json(&dir.join("manifest.json"));
    let reference = load_json(&dir.join("reference.json"));

    let manifest_fixtures = manifest["fixtures"].as_array().unwrap();
    let reference_fixtures = reference["fixtures"].as_array().unwrap();
    assert_eq!(
        manifest_fixtures.len(),
        reference_fixtures.len(),
        "manifest and reference fixture counts differ"
    );

    for (entry, gold) in manifest_fixtures.iter().zip(reference_fixtures) {
        let name = entry["name"].as_str().unwrap();
        assert_eq!(
            gold["name"].as_str().unwrap(),
            name,
            "fixture order differs"
        );
        let blob = std::fs::read(dir.join(entry["file"].as_str().unwrap())).expect("blob");
        let got = replay(entry, &blob);
        let want = gold["frames"].as_array().unwrap();
        assert_eq!(got.len(), want.len(), "{name}: frame count differs");

        for (index, ((cut, age, predictors, previous), frame)) in
            got.iter().zip(want.iter()).enumerate()
        {
            assert_eq!(
                *cut,
                frame["cut"].as_bool().unwrap(),
                "{name} frame {index}: cut decision differs from pinned WWXD"
            );
            assert_eq!(
                *age,
                frame["shot_age"].as_i64().unwrap() as i32,
                "{name} frame {index}: shot age differs from pinned WWXD"
            );
            assert_eq!(
                *predictors,
                frame["predictors"].as_u64().unwrap(),
                "{name} frame {index}: predictor-array digest differs from pinned WWXD"
            );
            assert_eq!(
                *previous,
                frame["previous"].as_u64().unwrap(),
                "{name} frame {index}: padded-plane digest differs from pinned WWXD"
            );
        }
    }
}

#[test]
fn the_detector_never_emits_frame_zero_as_a_boundary() {
    // The detector must never emit frame 0 as a cut.
    let dir = fixture_dir();
    let manifest = load_json(&dir.join("manifest.json"));
    for entry in manifest["fixtures"].as_array().unwrap() {
        let width = entry["width"].as_i64().unwrap() as u32;
        let height = entry["height"].as_i64().unwrap() as u32;
        let stride = entry["stride"].as_i64().unwrap() as usize;
        let blob = std::fs::read(dir.join(entry["file"].as_str().unwrap())).expect("blob");

        let mut detector = Detector::new(width, height).unwrap();
        let frame = DetectorFrame {
            index: SourceFrameIndex::new(0),
            width,
            height,
            stride,
            luma: &blob[..(height as usize) * stride],
        };
        let decision = detector.process(frame).unwrap();
        assert!(
            decision.boundary.is_none(),
            "{}: frame 0 was reported as a boundary",
            entry["name"].as_str().unwrap()
        );
    }
}
